/**
 * Refresh the documentation's copy of the published EverythingStar FOSS library.
 *
 * `tests/e2e/docs-library/` is the mock the capture tests see: the real
 * playlist, its songs' cover art at 96×96, and nothing else — the song
 * documents and charts are generated by `docs-library.ts`. This script is the
 * only thing that touches the network, and it is not part of any gate: a
 * snapshot is refreshed on purpose when the published library changes.
 *
 *   bun run docs:library
 *
 * ffmpeg is required to downscale the covers; the alternative is a hundred
 * kilobytes of full-size album art in a test fixture.
 */
import { mkdtempSync, mkdirSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

const SOURCE =
  "https://raw.githubusercontent.com/HappyPaul55/everythingstar-foss/main/songs/playlist.json";
const ROOT = join(import.meta.dir, "..");
const OUT = join(ROOT, "tests", "e2e", "docs-library");
const COVERS = join(OUT, "covers");

interface Entry {
  id: string;
  art?: string;
}

interface Playlist {
  songs: Entry[];
}

const response = await fetch(SOURCE);
if (!response.ok) throw new Error(`docs:library: ${SOURCE} answered ${response.status}`);
const playlist = (await response.json()) as Playlist;

mkdirSync(COVERS, { recursive: true });
await Bun.write(join(OUT, "playlist.json"), `${JSON.stringify(playlist, null, 2)}\n`);

const temp = mkdtempSync(join(tmpdir(), "docs-library-"));

try {
  let written = 0;
  for (const song of playlist.songs) {
    if (!song.art) continue;
    const url = new URL(song.art, SOURCE).href;
    const image = await fetch(url);
    if (!image.ok) throw new Error(`docs:library: ${url} answered ${image.status}`);
    const input = join(temp, `${song.id}.image`);
    await Bun.write(input, await image.arrayBuffer());

    // Square, small, and WebP: 37 covers are then ~150 KB rather than ~8 MB.
    const ffmpeg = Bun.spawnSync(
      [
        "ffmpeg",
        "-y",
        "-loglevel",
        "error",
        "-i",
        input,
        "-vf",
        "scale=96:96:force_original_aspect_ratio=increase,crop=96:96",
        "-c:v",
        "libwebp",
        "-quality",
        "72",
        join(COVERS, `${song.id}.webp`),
      ],
      { stdout: "pipe", stderr: "pipe" },
    );
    if (ffmpeg.exitCode !== 0) {
      throw new Error(`docs:library: ffmpeg failed for ${song.id}: ${ffmpeg.stderr.toString()}`);
    }
    written += 1;
  }

  console.log(`docs:library: ${playlist.songs.length} songs, ${written} covers → tests/e2e/docs-library/`);
} finally {
  rmSync(temp, { recursive: true, force: true });
}
